// === Tab: Card ===
class Card {
	constructor(pos, front, suit, vnum, val, cid, alt) {
		this.pos = createVector(random(-width/3,width/3), height / 3 + random(-height/12, height/12));
		this.tpos = createVector(0, height / 3);
		this.apos = createVector(0, 0);
		this.opos = createVector(pos.x, pos.y);
		this.ang = random(TAU);
		this.tang = 0;
		this.txt = front;
		this.suit = suit;
		this.vnum = vnum;
		this.val = val;
		this.cid = cid;
		this.w = this.txt.width * 1.05;
		this.h = this.txt.height;
		this.fang = TAU;
		this.tfang = TAU;
		this.alt = alt;
		this.fanang = 0;
		this.oid = cid;
	}
	show() {
		push();
		translate(this.pos);
		rotate(this.ang);
		scale(0.225 - 0.025 * cos(this.fang));
		fill(255);
		stroke(100);
		rect(0, 0, this.w * 1.05, this.h * 1.05, this.w / 20);
		if (this.fang < PI) image(this.txt, 0, 0, this.w, this.h);
		else image(back, 0, 0, this.w, this.h);
		fill(0);
		pop();
	}
	move() {
		this.fang = lerp(this.fang, this.tfang, 0.1);
		this.pos.lerp(this.tpos, 0.1);
		this.ang = lerp(this.ang, this.tang, 0.2);
		this.w = 0.5 * (this.txt.width * 1.02) + 0.5 * (this.txt.width * 1.02) * cos(this.fang);
	}
}

