//For the #WCCChallenge, theme: "cards"

let cimg;
let cards = [];
let suits = ['spades', 'hearts', 'diamonds', 'clubs']
let vals = ['ace', 'two', 'three', 'four', 'five', 'six', 'seven', 'eight', 'nine', 'ten', 'jack', 'queen', 'king'];
let mode = -1;
let deal = [];

function preload() {
	cimg = loadImage('file:///Users/unclerm/Vibe Coding/4K MV Visual Integration Editor/assets_cache/deck.png');
	back = loadImage('file:///Users/unclerm/Vibe Coding/4K MV Visual Integration Editor/assets_cache/back.png');
}

function setup() {
	createCanvas(windowWidth, windowHeight);
	back.resize(cimg.width / 14, 0);
	textAlign(CENTER, CENTER);
	imageMode(CENTER);
	rectMode(CENTER);
	createDeck();
	frameCount=-50;
}

function createDeck() {
	let sindex = 0;
	let cid = 0;
	let alt = 0;
	for (let y = 0; y < cimg.height; y += (Math.max(0.001, Math.abs(cimg.height / 4)) || 1)) {
		let cval = 0;
		for (let x = 0; x < cimg.width; x += (Math.max(0.001, Math.abs(cimg.width / 13)) || 1)) {
			let cx = -(cimg.width / 2) + x;
			let cy = -(cimg.height / 2) + y;
			alt = ((4 * cid) % 52) + sindex;
			cards.push(new Card(createVector((cx + cimg.width / 26) / 4, (cy + cimg.height / 8) / 4), cimg.get(x, y, cimg.width / 13, cimg.height / 4), suits[sindex], cval, vals[cval], cid, alt));
			cval += 1;
			cid += 1;
		}
		sindex += 1;
	}
	for (let i = 0; i < cards.length; i++) {
		cards[i].apos.x = cards[cards[i].alt].opos.x;
		cards[i].apos.y = cards[cards[i].alt].opos.y;
	}
}

function draw() {
	translate(width / 2, height / 2);
	background(0, 0, 20,150);
//	scale(height/566);
	if (mode < 5 || mode > 8) {
		for (let i = cards.length - 1; i >= 0; i--) {
			if (frameCount > 2 * cards[i].cid) cards[i].move();
			cards[i].show();
		}
	} else {
		for (let i = 0; i < cards.length; i++) {
			if (frameCount > 2 * cards[i].cid) cards[i].move();
			cards[i].show();
		}
	}
}

function mouseClicked() {
	mode = (mode + 1) % 12;
	switch (mode) {
		case 0:
			sortCards();
			break;

		case 1:
			unFlipAll();
			break;

		case 2:
			shuffleCards();
			break;

		case 3:
			altArrange();
			break;

		case 4:
			flipAll();
			break;

		case 5:
			makePile();
			break;

		case 6:
			fanCards();
			break;

		case 7:
			flipAll();
			break;

		case 8:
			makePile();
			break;

		case 9:
			blackjackDeal();
			break;

		case 10:
			showSecond();
			break;

		case 11:
			makePile();
			break;
	}
}

function shuffleCards() {
	frameCount = 0;
	for (var i = cards.length - 1; i > 0; i--) {
		var j = Math.floor(Math.random() * (i + 1));
		[cards[i].tpos.x, cards[j].tpos.x] = [cards[j].tpos.x, cards[i].tpos.x];
		[cards[i].tpos.y, cards[j].tpos.y] = [cards[j].tpos.y, cards[i].tpos.y];
		[cards[i].tang, cards[j].tang] = [cards[j].tang, cards[i].tang];
	}
}

function sortCards() {
	frameCount = 0;
	for (let c of cards) {
		c.tang = 0;
		c.tpos.x = c.opos.x;
		c.tpos.y = c.opos.y;
	}
}

function flipAll() {
	frameCount = 0;
	for (let c of cards) {
		c.tang += random(-0.2, 0.2);
		c.tfang = TAU;
	}
}

function unFlipAll() {
	frameCount = 0;
	for (let c of cards) {
		c.tang = random(-0.2, 0.2);
		c.tfang = 0;
	}
}

function makePile() {
	frameCount = 0;
	for (let c of cards) {
		c.cid = c.oid;
	}
	for (let c of cards) {
		c.tang = 0;
		c.tfang = TAU;
		c.tpos.x = 0;
		c.tpos.y = height / 3;
	}
}

function fanCards() {
	frameCount = 0;
	let ang = -PI;
	for (let c of cards) {
		c.tang = (HALF_PI + ang);
		c.fanang = (HALF_PI + ang);
		c.tfang = 0;
		c.tpos.x = (width / 2.5) * cos(ang);
		c.tpos.y = (height / 3) * sin(ang);
		ang += PI / 51;
	}
}

function altArrange() {
	frameCount = 0;
	for (let c of cards) {
		c.tang = random(-0.2, 0.2);
		c.tpos.x = c.apos.x;
		c.tpos.y = c.apos.y;
	}
}

function blackjackDeal() {
	frameCount = 0;
	deal = [];
	let possibles = [];
	for (let i = 0; i < 52; i++) {
		possibles.push(i);
	}
	for (let i = 0; i < 8; i++) {
		let pick = floor(random(possibles.length));
		deal.push(possibles[pick]);
		possibles.splice(pick, 1);
	}
	deal.sort(function(a, b) {
		return b - a;
	});
	for (let i = 0; i < deal.length; i++) {
		let xshift = -cimg.width / 600;
		let yshift = -cimg.width / 600;
		let ang = -PI + (i * HALF_PI);
		if (i < 4) {
			cards[deal[i]].tfang = 0;
			if (i % 1 == 0) {
				xshift = cimg.width / 300;
			} else {
				yshift = cimg.width / 300;
			}
		}
		cards[deal[i]].tpos.x = (width / 4) * cos(ang) + xshift;
		cards[deal[i]].tpos.y = -(height / 8) + (height / 6) * sin(ang) + yshift;
		cards[deal[i]].tang = ang + HALF_PI;
		cards[deal[i]].cid = 3 * i;
	}
}

function showSecond() {
	frameCount = 0;
	for (let i = 4; i < 8; i++) {
		cards[deal[i]].cid = 5 * (i-4);
	}
	for (let i = 4; i < 8; i++) {
		cards[deal[i]].tfang = 0;
		cards[deal[i]].tang += random(-0.2, 0.2);
	}
}

function keyPressed() {
	if (keyCode == UP_ARROW) blackjackDeal();
	if (keyCode == DOWN_ARROW) makePile();
	if (keyCode == RIGHT_ARROW) showSecond();
}

// 1. 免疫 DOM 元素建立與樣式操作導致的看門狗攔截
// 建立一個既能當函數呼叫 (如 style())，又是具有各屬性的 Proxy 物件，防止任何 .style、.style()、.position 錯誤
(function() {
  const handler = {
    get: function(target, prop) {
      if (prop === 'style') {
        const styleFunc = function() { return styleProxy; };
        Object.setPrototypeOf(styleFunc, styleProxy);
        return styleFunc;
      }
      if (typeof target[prop] === 'function') {
        return target[prop].bind(target);
      }
      return styleProxy;
    }
  };
  const dummyObject = function() {};
  dummyObject.position = function() { return dummyObject; };
  dummyObject.style = function() { return dummyObject; };
  dummyObject.size = function() { return dummyObject; };
  dummyObject.parent = function() { return dummyObject; };
  dummyObject.id = function() { return ""; };
  dummyObject.class = function() { return dummyObject; };
  dummyObject.mousePressed = function() { return dummyObject; };
  dummyObject.mouseOver = function() { return dummyObject; };
  dummyObject.changed = function() { return dummyObject; };
  dummyObject.html = function() { return dummyObject; };
  dummyObject.value = function() { return 0; };

  const styleProxy = new Proxy(dummyObject, handler);

  if (typeof createP === 'undefined') { window.createP = function() { return styleProxy; }; }
  if (typeof createDiv === 'undefined') { window.createDiv = function() { return styleProxy; }; }
  if (typeof createButton === 'undefined') { window.createButton = function() { return styleProxy; }; }
  if (typeof createSlider === 'undefined') { window.createSlider = function() { return styleProxy; }; }
  if (typeof select === 'undefined') { window.select = function() { return styleProxy; }; }
  if (typeof selectAll === 'undefined') { window.selectAll = function() { return [styleProxy]; }; }
})();

// 1.2 免疫 HTML 屬性與 Element.prototype.style 崩潰 (確保 style 與 checked 既可以當物件又可以當函數呼叫)
try {
  if (typeof Element !== 'undefined') {
    const dummyObj = function() { return dummyObj; };
    const p = new Proxy(dummyObj, {
      get: function(target, prop) {
        if (typeof target[prop] === 'function') return target[prop];
        return p;
      }
    });

    // 用屬性定義防止被覆寫
    Object.defineProperty(Element.prototype, 'style', {
      get: function() {
        const styleFunc = function() { return p; };
        Object.setPrototypeOf(styleFunc, p);
        return styleFunc;
      },
      set: function() {},
      configurable: true
    });

    Object.defineProperty(Element.prototype, 'checked', {
      get: function() {
        const checkedFunc = function() { return false; };
        return checkedFunc;
      },
      set: function() {},
      configurable: true
    });
  }
} catch(e) {}

// 1.3 免疫 HTMLInputElement.size = 0 或非法負數導致的瀏覽器拋錯
